1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns the owner's {@code membershipLevelCap}: a new owner's reported
10	 * {@code membershipLevel} cannot exceed one above the current maximum level among the
11	 * other members of their household. The cap is the highest {@link Owner#getMembershipLevel()}
12	 * over the already-saved, non-deleted owners that share this owner's {@code householdId},
13	 * plus one. When the household has no existing member, no cap applies (the field stays
14	 * {@code null}).
15	 *
16	 * <p>A <em>declared</em> household member ({@code sharesHousehold: true}) is exempt: it has
17	 * opted into the household and earns its level from genuine participation (the household-size
18	 * points), so its points-derived level stands uncapped. The cap therefore governs an owner
19	 * that merely shares a household key without declaring membership.
20	 *
21	 * <p>Runs after {@link AssignHousehold} (which assigns the shared {@code householdId}) and
22	 * the household/namesake counts, and before {@link SaveOwner} in the
23	 * {@code POST /api/owners} pipeline, so the members it reads over the repository exclude
24	 * the owner being created. It mutates the built {@link Owner} in place (see {@code @Val}
25	 * semantics), and the cap is persisted so later reads report the capped level. Existing
26	 * members contribute their own (already-capped) level, so the ceiling propagates through
27	 * the household as members are added.
28	 */
29	public class CapMembershipLevel {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
32	            OwnerRepository ownerRepository) {
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return; // a declared household member earns its level uncapped
35	        }
36	        String householdId = owner.getHouseholdId();
37	        if (householdId == null) {
38	            return;
39	        }
40	        Integer maxLevel = null;
41	        for (Owner existing : ownerRepository.findAll()) {
42	            if (existing == owner || existing.isDeleted()
43	                    || !householdId.equals(existing.getHouseholdId())) {
44	                continue;
45	            }
46	            int level = existing.getMembershipLevel();
47	            if (maxLevel == null || level > maxLevel) {
48	                maxLevel = level;
49	            }
50	        }
51	        if (maxLevel != null) {
52	            owner.setMembershipLevelCap(maxLevel + 1);
53	        }
54	    }
55	}
