268	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
269	        this.possibleDuplicateOf = possibleDuplicateOf;
270	    }
271	
272	    /**
273	     * Whether this owner has been soft-deleted. A newly created owner is not deleted;
274	     * {@code DELETE /api/owners/{id}} sets this true while retaining the row, and the
275	     * create-owner duplicate/identity checks ignore owners flagged deleted.
276	     */
277	    public boolean isDeleted() {
278	        return this.deleted;
279	    }
280	
281	    public void setDeleted(boolean deleted) {
282	        this.deleted = deleted;
283	    }
284	
285	    /**
286	     * The owner's membership points, accumulated from four factors: start at 0, add 2
287	     * when an email is present, add 1 when {@code namesakeCount} is 0, add 2 for a
288	     * household of 3 or more members, and add 3 when the owner's tenure spans at least
289	     * one elapsed fiscal year. The tenure points are the only route to 6 or more:
290	     * because a newly created owner has zero elapsed fiscal years of tenure, a new owner
291	     * scores at most 5 points (2 email + 1 namesake + 2 household).
292	     */
293	    @Transient
294	    public int getMembershipPoints() {
295	        int points = 0;
296	        if (this.email != null && !this.email.isBlank()) {
297	            points += 2;
298	        }
299	        if (this.namesakeCount != null && this.namesakeCount == 0) {
300	            points += 1;
301	        }
302	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
303	            points += 2;
304	        }
305	        if (getTenureFiscalYears() >= 1) {
306	            points += 3;
307	        }
308	        return points;
309	    }
310	
311	    /**
312	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
313	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
314	     * created owner scores at most 5 points (tenure being the only route to 6), a new
315	     * owner never exceeds level 3.
316	     *
317	     * <p>The result is then bounded by {@code membershipLevelCap} when one is set: a new
318	     * owner's level cannot exceed one above the highest level among the existing members
319	     * of their household, so the reported level is the lesser of the points-derived level
320	     * and that cap.
321	     */
