76	
77	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
78	
79	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
80	        OwnerPageDto ownerPageDto = new OwnerPageDto();
81	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
82	        ownerPageDto.setPage(ownerPage.getNumber());
83	        ownerPageDto.setSize(ownerPage.getSize());
84	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
85	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
86	        return ownerPageDto;
87	    }
